sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    /*
    The Script Include - **MSSCustodyBulkUtils** is and method **bulkCheckerTaskVerification** is accessed
    which will evaluate if the current assigned user holds allowed band limit and return true or false to the On Submit client
    script - **Bulk Checker Task Band Limit Check** on **MSS Custody Bulk Form** table
    trdAccess - returns true or false based on the assigned user eligibility
    highValueTradeID - trades which hold high Settlement/Nominal settlement amount than users allowed limit
    */

    var bulkID = current.getValue('sys_id');
    var bulkAssignee = gs.getUserID(); //current.getValue('assigned_to'); modified as per 4172

    var tradApprChk = new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().bulkCheckerTaskVerification(bulkID, bulkAssignee);
    var trdChk = new global.JSON.parse(tradApprChk);
    var trdAccess = trdChk.tradeEligibility;
    var highValueTradeID = trdChk.highValTrades;


    var unEligTradRec = 'Associated trade(s) ' + highValueTradeID + " holds settlement/nominal settlement amount more than assigned user's allowed band limit.";
    g_scratchpad.approvalAccessChecker = trdAccess;
    g_scratchpad.usrChekcerBulkMessage = unEligTradRec;

})(current, previous);
